package com.example.library;
import org.springframework.boot.*;import org.springframework.boot.autoconfigure.*;import org.springframework.stereotype.*;import org.springframework.web.bind.annotation.*;import org.springframework.ui.Model;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.core.type.TypeReference;import java.nio.file.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;
@SpringBootApplication public class LibraryApp{public static void main(String[]a){SpringApplication.run(LibraryApp.class,a);}}
class Book{public long id;public String title="",author="";public int copies=1,available=1;public Book(){}}
class Loan{public long id,bookId;public String borrower="",issued="",due="";public boolean returned;public double fine;public Loan(){}}
@Component class Store{ObjectMapper m=new ObjectMapper();Path bp=Path.of("data/books.json"),lp=Path.of("data/loans.json");synchronized <T>List<T> read(Path p){try{Files.createDirectories(p.getParent());if(!Files.exists(p))Files.writeString(p,"[]");return m.readValue(p.toFile(),new TypeReference<List<T>>(){});}catch(Exception e){throw new RuntimeException(e);}}synchronized void save(Object x,Path p){try{m.writerWithDefaultPrettyPrinter().writeValue(p.toFile(),x);}catch(Exception e){throw new RuntimeException(e);}}}
@Controller class Web{Store s;Web(Store s){this.s=s;}@GetMapping("/")String home(Model m){m.addAttribute("books",s.<Book>read(s.bp));m.addAttribute("loans",s.<Loan>read(s.lp));return "index";}@PostMapping("/book")String add(@RequestParam String title,@RequestParam String author,@RequestParam int copies){var l=s.<Book>read(s.bp);var b=new Book();b.id=l.stream().mapToLong(x->x.id).max().orElse(0)+1;b.title=title;b.author=author;b.copies=copies;b.available=copies;l.add(b);s.save(l,s.bp);return "redirect:/";}@PostMapping("/issue")String issue(@RequestParam long bookId,@RequestParam String borrower){var bs=s.<Book>read(s.bp);var b=bs.stream().filter(x->x.id==bookId).findFirst().orElse(null);if(b!=null&&b.available>0&&!borrower.isBlank()){b.available--;s.save(bs,s.bp);var ls=s.<Loan>read(s.lp);var l=new Loan();l.id=ls.stream().mapToLong(x->x.id).max().orElse(0)+1;l.bookId=bookId;l.borrower=borrower;l.issued=LocalDate.now().toString();l.due=LocalDate.now().plusDays(14).toString();ls.add(l);s.save(ls,s.lp);}return "redirect:/";}@GetMapping("/return/{id}")String ret(@PathVariable long id){var ls=s.<Loan>read(s.lp);var l=ls.stream().filter(x->x.id==id&&!x.returned).findFirst().orElse(null);if(l!=null){l.returned=true;l.fine=Math.max(0,ChronoUnit.DAYS.between(LocalDate.parse(l.due),LocalDate.now()))*5.0;s.save(ls,s.lp);var bs=s.<Book>read(s.bp);bs.stream().filter(b->b.id==l.bookId).findFirst().ifPresent(b->b.available++);s.save(bs,s.bp);}return "redirect:/";}}
